import React, {useEffect, useState, useCallback, useRef} from 'react';
import {Wrench, LayoutDashboard, Truck, Gauge, ClipboardList, CalendarDays, Bell, Users, Menu, Search, ChevronDown, ChevronLeft, ChevronRight, Download, Plus, Check, X, Pencil, Camera, LogOut, AlertTriangle, CheckCircle2, Wifi, WifiOff, FileText, Save, ArrowUpRight, Mail} from 'lucide-react';
import {api, initCSRF, download, pendingReadings, queueReading, readingForm, syncReadings} from './api';

const labels = {operational:'Operativo',upcoming:'Próximo a mantención',required:'Mantención requerida',overdue:'Mantención vencida'};
const roles = {admin:'Administrador',planner:'Planificador',helper:'Ayudante',chief:'Jefe de operaciones'};
const modules = [{id:'fleet',label:'Estado de la flota',icon:LayoutDashboard},{id:'equipment',label:'Gestión de equipos',icon:Truck},
  {id:'readings',label:'Lecturas de horómetro',icon:Gauge},{id:'detail',label:'Ficha técnica / Historial',icon:ClipboardList},
  {id:'maintenance',label:'Registro de mantención',icon:Wrench},{id:'calendar',label:'Calendario y reportes',icon:CalendarDays},
  {id:'alerts',label:'Alertas de mantención',icon:Bell},{id:'users',label:'Usuarios y roles',icon:Users}];
const fmt = value => Number(value ?? 0).toLocaleString('es-CL',{maximumFractionDigits:0});
const date = value => value ? new Date(value).toLocaleDateString('es-CL') : '—';
const stamp = value => value ? new Date(value).toLocaleString('es-CL',{dateStyle:'short',timeStyle:'short'}) : '—';
const localInput = (value = new Date()) => {const d=new Date(value); return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
const today = () => localInput().slice(0,10);
function Logo(){return <div className="brand"><span className="brand-mark"><Wrench size={21}/></span><span>VILA’S MOTOR</span></div>;}
function Button({children,icon:Icon,onClick,kind='',...rest}){return <button className={`vm-button ${kind}`} onClick={onClick} {...rest}>{Icon&&<Icon size={14}/>} {children}</button>;}
function Badge({status}){return <span className={`state-badge ${status}`}><span>●</span> {labels[status]||status}</span>;}
function Progress({equipment}){return <div className={`progress-block ${equipment.status}`}><div><strong>{fmt(equipment.progress)}% usado</strong><span>{Number(equipment.remaining)<0?`${fmt(Math.abs(equipment.remaining))} ${equipment.unit} vencido`:Number(equipment.remaining)===0?'Requerida ahora · 0 '+equipment.unit:`${fmt(equipment.remaining)} ${equipment.unit} restantes`}</span></div><div className="progress-track"><i style={{width:`${Math.min(equipment.progress,100)}%`}}/></div></div>;}
function Field({label,children,...props}){return <label className="field"><span>{label}</span>{children?React.cloneElement(children,{'aria-label':label}):<input aria-label={label} {...props}/>}</label>;}
function Select({children,...props}){return <select {...props}>{children}</select>;}
function Notice({kind='green',children}){const Icon=kind==='green'?CheckCircle2:AlertTriangle;return <div className={`notice ${kind}`}><Icon size={17}/><div>{children}</div></div>;}
function Empty({children='No hay registros para los filtros seleccionados.'}){return <div className="empty-state">{children}</div>;}
function PageHeader({title,subtitle,children}){return <div className="page-heading"><div><h1>{title}</h1><p>{subtitle}</p></div><div className="heading-actions">{children}</div></div>;}
function SearchBox({value,onChange,placeholder='Buscar código o modelo',expanded=false}){return <label className={`search-control ${expanded?'mobile-expanded':''}`}><Search size={15}/><input aria-label={placeholder} value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/></label>;}
function Stat({label,value,note,status=''}){return <div className={`stat ${status}`}><span>● {label}</span><strong>{value}</strong><small>{note}</small></div>;}
function Modal({title,children,onClose}){
  const ref=useRef(null);
  useEffect(()=>{const previous=document.activeElement; ref.current?.focus(); const key=e=>{if(e.key==='Escape')onClose();if(e.key==='Tab'){const nodes=ref.current?.querySelectorAll('button,input,select,textarea,a[href]');if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};document.addEventListener('keydown',key);return()=>{document.removeEventListener('keydown',key);previous?.focus();};},[onClose]);
  return <div className="modal-backdrop-vm" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="vm-modal" role="dialog" aria-modal="true" aria-label={title} tabIndex={-1} ref={ref}><div className="modal-title"><h2>{title}</h2><button className="icon-button" aria-label="Cerrar" onClick={onClose}><X size={20}/></button></div>{children}</div></div>;
}

function Login({onLogin}){
  const params=new URLSearchParams(location.search);
  const [recover,setRecover]=useState(true),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[message,setMessage]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false),[resetDone,setResetDone]=useState(false);
  const resetting=params.has('reset')&&!resetDone;
  async function submit(e){e.preventDefault();setError('');setMessage('');setBusy(true);try{
    if(resetting){await api('auth/reset/confirm/',{method:'POST',body:{uid:params.get('reset'),token:params.get('token'),password}});history.replaceState({},'',location.pathname);setResetDone(true);setPassword('');setMessage('Contraseña actualizada. Ingresa con tu nueva clave.');}
    else {await api('auth/login/',{method:'POST',body:{email,password}});onLogin(await api('auth/me/'));}
  }catch(e){setError(e.message);}finally{setBusy(false);}}
  async function recoverAccess(e){e.preventDefault();setError('');setBusy(true);try{const result=await api('auth/reset/',{method:'POST',body:{email}});setMessage(result.detail);}catch(e){setError(e.message);}finally{setBusy(false);}}
  return <div className="login-page"><div className="login-layout"><div className="login-photo"><div className="north-label">NORTE / OPERACIONES</div><div className="login-photo-content"><h1>CADA MÁQUINA.<br/>CADA HORA.<br/>BAJO CONTROL.</h1><p>Un solo espacio de trabajo para la salud de tu flota, planificación de mantenciones y lecturas confiables de cada máquina.</p><div className="login-counters"><div><strong>06</strong><span>MÁQUINAS PILOTO</span></div><div><strong>04</strong><span>ROLES DE ACCESO</span></div><div><strong>01</strong><span>VISTA DE FLOTA</span></div></div></div></div>
    <div className="login-content"><Logo/><div className="login-form-area"><span className="eyebrow">GESTIÓN DE MANTENCIÓN DE FLOTA</span><h1>{resetting?'Restablecer contraseña':'Vila’s Motor'}</h1><p>{resetting?'Define una nueva contraseña para recuperar tu acceso.':'Inicia sesión para mantener tus operaciones en marcha.'}</p>
      <form onSubmit={submit}><Field label="Correo electrónico"><input type="email" required autoComplete="username" value={email} onChange={e=>setEmail(e.target.value)} placeholder="james@vilasmotor.cl" disabled={resetting}/></Field><Field label={resetting?'Nueva contraseña':'Contraseña'}><input type="password" required minLength={resetting?8:1} autoComplete={resetting?'new-password':'current-password'} value={password} onChange={e=>setPassword(e.target.value)} placeholder="••••••••"/></Field>
      {!resetting&&<div className="login-options"><span>Sesión protegida · 2 horas</span><button type="button" className="text-button red-text" onClick={()=>{setRecover(!recover);setMessage('');}}>¿Olvidaste tu contraseña?</button></div>}
      <Button kind="primary full" icon={Check} disabled={busy}>{busy?'Procesando…':resetting?'Guardar contraseña':'Ingresar'}</Button></form>
      <div className="access-note"><CheckCircle2 size={13}/> Acceso basado en roles</div>
      {recover&&<form className="panel recovery" onSubmit={recoverAccess}><div className="modal-title"><h2>Recuperar acceso</h2><button type="button" className="icon-button" onClick={()=>setRecover(false)} aria-label="Cerrar recuperación"><X size={14}/></button></div><p>Ingresa tu correo corporativo. Te enviaremos un enlace seguro de restablecimiento válido por 30 minutos.</p><Field label="Correo de recuperación"><input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="james@vilasmotor.cl"/></Field><Button kind="full" icon={Mail} disabled={busy}>Enviar enlace de restablecimiento</Button></form>}
      {error&&<div role="alert" className="form-error">{error}</div>}{message&&<Notice>{message}</Notice>}
    </div><div className="login-footer"><span>Uso exclusivo del área de Planificación y administración.<br/>© 2026 Vila’s Motor</span><span>Protección · Trazabilidad · Ayuda</span></div></div></div></div>;
}

function Fleet({equipment,can,navigate,exportFile}){
  const [search,setSearch]=useState(''),[type,setType]=useState(''),[status,setStatus]=useState(''),[mobilePage,setMobilePage]=useState(0),[showSearch,setShowSearch]=useState(false);
  useEffect(()=>setMobilePage(0),[search,type,status]);
  const active=equipment.filter(e=>e.active), rows=active.filter(e=>`${e.code} ${e.name}`.toLowerCase().includes(search.toLowerCase())&&(!type||e.equipment_type===type)&&(!status||e.status===status));
  const priority={overdue:0,required:1,upcoming:2,operational:3}; rows.sort((a,b)=>priority[a.status]-priority[b.status]||a.code.localeCompare(b.code));
  return <><PageHeader title="ESTADO DE LA FLOTA" subtitle={<><span className="desktop-subtitle">Una vista clara de cada máquina, cuánto intervalo ha usado y cuándo necesita mantención.</span><span className="mobile-subtitle">Norte / {stamp(new Date())}</span></>}>{can('reading','C')&&<Button kind="primary" icon={Check} onClick={()=>navigate('readings')}>Registrar lectura</Button>}</PageHeader>
    <div className="stats-grid"><Stat label="Equipos activos" value={active.length} note="Flota · Datos centralizados"/><Stat label="Operativo" value={active.filter(e=>e.status==='operational').length} note="Sin alertas pendientes" status="operational"/><Stat label="Próximo a mantención" value={active.filter(e=>e.status==='upcoming').length} note="Planificar taller" status="upcoming"/><Stat label="Requerido / Vencido" value={`${active.filter(e=>e.status==='required').length.toString().padStart(2,'0')} / ${active.filter(e=>e.status==='overdue').length.toString().padStart(2,'0')}`} note="Atención inmediata" status="overdue"/></div>
    <div className="mobile-fleet-summary"><strong>{active.length} máquinas</strong><span className="red-text">{active.filter(e=>['required','overdue'].includes(e.status)).length} urgentes</span><span className="orange-text">{active.filter(e=>e.status==='upcoming').length} próximas</span></div><div className="toolbar"><SearchBox value={search} onChange={setSearch} expanded={showSearch}/><Select aria-label="Filtrar tipo de equipo" value={type} onChange={e=>setType(e.target.value)}><option value="">Todos los tipos de equipo</option>{[...new Set(active.map(e=>e.equipment_type))].map(t=><option key={t}>{t}</option>)}</Select><Select aria-label="Filtrar estado" value={status} onChange={e=>setStatus(e.target.value)}><option value="">Todos los estados</option>{Object.entries(labels).map(([s,l])=><option key={s} value={s}>{l}</option>)}</Select><button className="mobile-search-trigger icon-button" aria-label="Mostrar búsqueda" aria-expanded={showSearch} onClick={()=>setShowSearch(s=>!s)}><Search size={18}/></button><span className="muted toolbar-note">{rows.length} máquinas · Actualización en línea</span><Button icon={Download} onClick={()=>exportFile('xlsx')}>Exportar</Button></div>
    <div className="desktop-table table-responsive"><table className="vm-table"><thead><tr><th>EQUIPO</th><th>LECTURA ACTUAL</th><th>PRÓXIMA MANTENCIÓN</th><th>INTERVALO USADO</th><th>ESTADO</th><th/></tr></thead><tbody>{rows.map(e=><tr key={e.id}><td><strong>{e.code} · {e.name}</strong><small>{e.equipment_type}</small></td><td>{fmt(e.current_value)} {e.unit}</td><td>{fmt(e.next_service)} {e.unit}</td><td className="progress-cell"><Progress equipment={e}/></td><td><Badge status={e.status}/></td><td><button className="text-button red-text" onClick={()=>navigate('detail',e.id)}>Ver <ChevronDown size={10}/></button></td></tr>)}</tbody></table></div>
    <div className="mobile-equipment">{rows.slice(mobilePage*3,mobilePage*3+3).map(e=><button key={e.id} className="mobile-card" onClick={()=>navigate('detail',e.id)}><div><strong>{e.code} · {e.name}</strong><ChevronRight size={18}/></div><div><Badge status={e.status}/><small>{e.equipment_type}</small></div><p>{fmt(e.current_value)} {e.unit} · Próxima mantención {fmt(e.next_service)} {e.unit}</p><Progress equipment={e}/></button>)}{rows.length>0&&<div className="mobile-pagination"><span>{mobilePage*3+1}–{Math.min(mobilePage*3+3,rows.length)} de {rows.length} · Urgencia primero</span><div><button className="icon-button" aria-label="Página anterior" disabled={mobilePage===0} onClick={()=>setMobilePage(p=>p-1)}><ChevronLeft size={16}/></button><span>{mobilePage+1} / {Math.ceil(rows.length/3)}</span><button className="icon-button" aria-label="Página siguiente" disabled={(mobilePage+1)*3>=rows.length} onClick={()=>setMobilePage(p=>p+1)}><ChevronRight size={16}/></button></div></div>}</div>{!rows.length&&<Empty/>}
    <div className="two-notices"><Notice kind="red"><strong>{active.filter(e=>['required','overdue'].includes(e.status)).length} alertas críticas · {active.filter(e=>e.status==='upcoming').length} equipos requieren planificación</strong><p>Revisa las alertas antes de asignar una nueva jornada de trabajo.</p></Notice><Notice><strong>El progreso indica el intervalo consumido, no la disponibilidad del equipo.</strong><p>0–84%: planificar operaciones · 85–99%: próximo · 100%: requerido. Sobre el 100%: la barra se mantiene completa y muestra el atraso.</p></Notice></div></>;
}

const equipmentDefaults={code:'',name:'',equipment_type:'Excavadora',brand:'',model:'',serial_number:'',region:'Tarapacá',commune:'Alto Hospicio',location:'',responsible:'',unit:'hrs',interval:250,initial_value:0,initial_service_value:0,active:true};
function EquipmentEditor({item,onSave,onCancel,busy}){
  const [form,setForm]=useState({...equipmentDefaults,...item});
  useEffect(()=>setForm({...equipmentDefaults,...item}),[item]);
  const set=(key,value)=>setForm(f=>({...f,[key]:value}));
  function submit(e){e.preventDefault();const body={};Object.keys(equipmentDefaults).forEach(k=>body[k]=form[k]);onSave(body,item?.id);}
  return <form className="panel side-form" onSubmit={submit}><div className="panel-title"><h2>{item?.id?`Editar equipo · ${item.code}`:'Crear equipo'}</h2><Pencil size={15}/></div><div className="field-grid"><Field label="Código de equipo *" required value={form.code} onChange={e=>set('code',e.target.value)}/><Field label="Tipo *"><Select value={form.equipment_type} onChange={e=>set('equipment_type',e.target.value)}>{['Excavadora','Cargador frontal','Grúa horquilla','Camión tolva','Generador','Retroexcavadora','Luminaria','Manipulador telescópico'].map(t=><option key={t}>{t}</option>)}</Select></Field><Field label="Nombre / Modelo visible *" required value={form.name} onChange={e=>set('name',e.target.value)}/><Field label="Marca *" required value={form.brand} onChange={e=>set('brand',e.target.value)}/><Field label="Modelo *" required value={form.model} onChange={e=>set('model',e.target.value)}/><Field label="Número de serie *" required value={form.serial_number} onChange={e=>set('serial_number',e.target.value)}/><Field label="Unidad de medición"><Select value={form.unit} onChange={e=>set('unit',e.target.value)} disabled={!!item?.id}><option value="hrs">Horas</option><option value="km">Kilómetros</option></Select></Field><Field label="Intervalo de servicio *" type="number" min="1" required value={form.interval} onChange={e=>set('interval',e.target.value)}/><Field label="Lectura inicial *" type="number" min="0" step="0.01" required disabled={!!item?.id} value={form.initial_value} onChange={e=>set('initial_value',e.target.value)}/><Field label="Última mantención inicial *" type="number" min="0" step="0.01" required disabled={!!item?.id} value={form.initial_service_value} onChange={e=>set('initial_service_value',e.target.value)}/><Field label="Región *" required value={form.region} onChange={e=>set('region',e.target.value)}/><Field label="Comuna *" required value={form.commune} onChange={e=>set('commune',e.target.value)}/></div><Field label="Faena / ubicación" value={form.location} onChange={e=>set('location',e.target.value)}/><Field label="Responsable" value={form.responsible} onChange={e=>set('responsible',e.target.value)}/><div className="form-actions"><Button type="button" onClick={onCancel}>Cancelar</Button><Button kind="primary" icon={Check} disabled={busy}>Guardar cambios</Button></div></form>;
}
function EquipmentPage({equipment,can,navigate,mutate,busy,exportFile}){
  const [search,setSearch]=useState(''),[region,setRegion]=useState(''),[editing,setEditing]=useState(null),[confirm,setConfirm]=useState(null);
  const rows=equipment.filter(e=>`${e.code} ${e.name}`.toLowerCase().includes(search.toLowerCase())&&(!region||e.region===region));
  async function save(body,id){if(await mutate(`equipment/${id?id+'/':''}`,id?'PATCH':'POST',body))setEditing(null);}
  return <><PageHeader title="GESTIÓN DE EQUIPOS" subtitle="Crea, consulta, edita o desactiva equipos sin perder su historial de mantenciones.">{can('equipment','C')&&<Button icon={Check} kind="primary" onClick={()=>setEditing({})}>Crear equipo</Button>}</PageHeader><div className="toolbar"><SearchBox value={search} onChange={setSearch}/><Select aria-label="Filtrar región" value={region} onChange={e=>setRegion(e.target.value)}><option value="">Todas las regiones</option>{[...new Set(equipment.map(e=>e.region))].map(r=><option key={r}>{r}</option>)}</Select><Button icon={Download} onClick={()=>exportFile('xlsx')}>Exportar</Button><Button icon={FileText} onClick={()=>download('migration-template/','plantilla-equipos.csv')}>Plantilla de migración</Button></div><div className={`split-layout ${editing?'':'no-aside'}`}><div className="table-responsive"><table className="vm-table"><thead><tr><th>EQUIPO</th><th>ÚLTIMA LECTURA</th><th>UBICACIÓN</th><th>ACCIONES</th></tr></thead><tbody>{rows.map(e=><tr key={e.id} className={!e.active?'inactive-row':''}><td><strong>{e.code} · {e.name}</strong><small>{e.brand} {e.model}{!e.active?' · Inactivo':''}</small></td><td>{fmt(e.current_value)} {e.unit}</td><td>{e.region}<small>{e.commune}</small></td><td className="table-actions"><button className="text-button red-text" onClick={()=>navigate('detail',e.id)}>Consultar</button>{can('equipment','U')&&<button className="text-button red-text" onClick={()=>setEditing(e)}>Editar</button>}{e.active&&can('equipment','D')&&<button className="text-button red-text" onClick={()=>setConfirm(e)}>Desactivar</button>}</td></tr>)}</tbody></table>{!rows.length&&<Empty/>}<p className="table-note">{rows.length} equipos visibles · Los registros inactivos conservan sus lecturas y mantenciones.</p></div>{editing&&<EquipmentEditor item={editing} onSave={save} onCancel={()=>setEditing(null)} busy={busy}/>}</div><div className="two-notices"><Notice><strong>Historial protegido</strong><p>Las lecturas y las mantenciones permanecen vinculadas a cada equipo, incluso al desactivarlo.</p></Notice><Notice kind="yellow"><strong>Migración de registros existentes</strong><p>Descarga la plantilla y prepara tus datos. La importación histórica debe revisarse antes de cargar información real.</p></Notice></div>{confirm&&<Modal title={`¿Desactivar ${confirm.code}?`} onClose={()=>setConfirm(null)}><p>El equipo saldrá de la flota activa. Se conservarán sus lecturas, mantenciones y alertas históricas.</p><div className="form-actions"><Button onClick={()=>setConfirm(null)}>Mantener activo</Button><Button kind="primary" disabled={busy} onClick={async()=>{if(await mutate(`equipment/${confirm.id}/`,'DELETE'))setConfirm(null);}}>Desactivar equipo</Button></div></Modal>}</>;
}

function ReadingsPage({equipment,readings,can,mutate,busy,user,onQueued,exportFile}){
  const [filter,setFilter]=useState(''),[source,setSource]=useState(''),[editing,setEditing]=useState(null);
  const [form,setForm]=useState({equipment:equipment.find(e=>e.active)?.id||'',value:'',recorded_at:localInput(),note:'',evidence:null});
  const selected=equipment.find(e=>String(e.id)===String(form.equipment));
  const rows=readings.filter(r=>(!filter||String(r.equipment)===filter)&&(!source||r.source===source));
  const set=(key,value)=>setForm(f=>({...f,[key]:value}));
  async function submit(e){e.preventDefault();const data={equipment:form.equipment,value:form.value,recorded_at:new Date(form.recorded_at).toISOString(),note:form.note,evidence:form.evidence,client_id:editing?.client_id||crypto.randomUUID()};
    if(!navigator.onLine&&!editing){await queueReading(data,user.id);onQueued();set('value','');return;}
    if(await mutate(`readings/${editing?editing.id+'/':''}`,editing?'PATCH':'POST',readingForm(data))){setEditing(null);setForm(f=>({...f,value:'',note:'',evidence:null,recorded_at:localInput()}));}
  }
  return <><PageHeader title="REGISTRO DE LECTURAS DE HORÓMETRO" subtitle="Consulta las lecturas recibidas, sus evidencias, su validación y quién realizó cada registro."><Button icon={Download} onClick={()=>exportFile('xlsx')}>Exportar estado</Button></PageHeader><div className="toolbar"><Select aria-label="Filtrar lecturas por equipo" value={filter} onChange={e=>setFilter(e.target.value)}><option value="">Todos los equipos</option>{equipment.map(e=><option key={e.id} value={e.id}>{e.code} · {e.name}</option>)}</Select><Select aria-label="Filtrar fuente" value={source} onChange={e=>setSource(e.target.value)}><option value="">Todas las fuentes</option><option value="manual">Manual</option><option value="ocr">OCR por foto</option><option value="sensor">Sensor</option></Select><span className="muted">{rows.length} lecturas registradas</span></div><div className={`split-layout ${can('reading','C')?'':'no-aside'}`}><div><div className="table-responsive"><table className="vm-table readings-table"><thead><tr><th>FECHA / HORA</th><th>EQUIPO</th><th>VALOR</th><th>EVIDENCIA</th><th>FUENTE</th><th/></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{date(r.recorded_at)}<small>{new Date(r.recorded_at).toLocaleTimeString('es-CL',{hour:'2-digit',minute:'2-digit'})}</small></td><td>{r.equipment_code} / {r.equipment_name}</td><td>{fmt(r.value)} {equipment.find(e=>e.id===r.equipment)?.unit}</td><td>{r.evidence?<a href={r.evidence} target="_blank" rel="noreferrer"><img className="evidence-thumb" src={r.evidence} alt="Foto del horómetro"/></a>:<small>Sin foto histórica</small>}{r.confidence!=null&&<small className={Number(r.confidence)<95?'orange-text':'green-text'}>{r.confidence}%</small>}</td><td>{r.source==='ocr'?'OCR por foto':r.source==='sensor'?'Sensor':'Manual'}<small className="green-text">{r.registered_by}</small></td><td>{can('reading','U')&&<button className="text-button red-text" onClick={()=>{setEditing(r);setForm({equipment:r.equipment,value:r.value,recorded_at:localInput(r.recorded_at),note:r.note,evidence:null});}}>Editar</button>}</td></tr>)}</tbody></table>{!rows.length&&<Empty/>}</div><Notice><strong>La evidencia permanece adjunta a la lectura.</strong><p>Las lecturas se validan contra su historial. Una lectura inferior a la anterior se rechaza sin modificar los registros.</p></Notice></div>{can('reading','C')&&<form className="panel side-form" onSubmit={submit}><h2>{editing?'Editar lectura':'Ingreso manual'}</h2><p>Horas reales · Evidencia</p><Field label="Equipo *"><Select required disabled={!!editing} value={form.equipment} onChange={e=>set('equipment',e.target.value)}>{equipment.filter(e=>e.active).map(e=><option key={e.id} value={e.id}>{e.code} · {e.name}</option>)}</Select></Field><Field label="Fecha y hora *"><input type="datetime-local" required max={localInput()} value={form.recorded_at} onChange={e=>set('recorded_at',e.target.value)}/></Field><div className="field-grid"><Field label="Valor de horómetro *"><input type="number" min="0" step="0.01" required value={form.value} onChange={e=>set('value',e.target.value)} placeholder={selected?.current_value}/></Field><Field label="Unidad"><input disabled value={selected?.unit||'hrs'}/></Field></div><small className="input-help">Lectura anterior: {fmt(selected?.current_value)} {selected?.unit}. Una lectura menor no se guardará.</small><label className="upload-area"><Camera size={23}/><strong>{form.evidence?.name||'Adjuntar foto del horómetro'}</strong><small>JPG / PNG / WEBP · Máximo 10 MB</small><input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>set('evidence',e.target.files[0]||null)}/></label><Field label="Nota / Fuente de lectura"><textarea rows="3" value={form.note} onChange={e=>set('note',e.target.value)} placeholder="Inspección rutinaria · Confirmación manual"/></Field><small className="input-help">Sin conexión: el registro se guarda en este dispositivo y se sincroniza al recuperar internet.</small><div className="form-actions">{editing&&<Button type="button" onClick={()=>{setEditing(null);set('value','');}}>Cancelar</Button>}<Button kind="primary" icon={Check} disabled={busy||!selected}>Guardar lectura</Button></div></form>}</div></>;
}

function DetailPage({equipment,selectedId,can,navigate,exportFile}){
  const selected=equipment.find(e=>e.id===selectedId)||equipment[0];
  const [tab,setTab]=useState('readings'),[history,setHistory]=useState(null),[error,setError]=useState('');
  useEffect(()=>{setHistory(null);if(selected)api(`equipment/${selected.id}/history/`).then(setHistory).catch(e=>setError(e.message));},[selected]);
  if(!selected)return <Empty>No hay equipos registrados.</Empty>;
  const e=history?.equipment||selected, last=history?.maintenances.find(m=>m.status==='completed');
  return <><PageHeader title="FICHA TÉCNICA DE EQUIPO" subtitle={`Flota / ${e.code} · Registros permanentes de lecturas, mantenciones y alertas.`}><Button icon={Download} onClick={()=>exportFile('pdf')}>Exportar estado de flota</Button>{can('maintenance','C')&&<Button icon={Wrench} onClick={()=>navigate('maintenance',e.id)}>Registrar mantención</Button>}</PageHeader><div className="toolbar"><Select aria-label="Seleccionar ficha de equipo" value={e.id} onChange={event=>navigate('detail',Number(event.target.value))}>{equipment.map(item=><option value={item.id} key={item.id}>{item.code} · {item.name}</option>)}</Select></div><div className="panel equipment-summary"><img src={e.photo||'/assets/excavator.jpg'} alt={`${e.equipment_type} · imagen de referencia`}/><div className="summary-text"><h2>{e.code} / {e.name}</h2><div className="summary-columns"><div><p>Tipo · {e.equipment_type}</p><p>Serie · {e.serial_number}</p><p>Marca · {e.brand} / Modelo · {e.model}</p></div><div><p>Faena · {e.location||'Sin asignar'}</p><p>Responsable · {e.responsible||'Sin asignar'}</p><p>{e.region} / {e.commune}</p></div></div></div><Badge status={e.status}/></div><div className="equipment-metrics"><div className="panel"><span className="eyebrow">LECTURA ACTUAL</span><h2>{fmt(e.current_value)} {e.unit}</h2></div><div className="panel"><span className="eyebrow">ÚLTIMA / PRÓXIMA MANTENCIÓN</span><h2>{fmt(e.last_service_value)} / {fmt(e.next_service)} {e.unit}</h2></div><div className="panel"><strong>Intervalo preventivo de {fmt(e.interval)} {e.unit}</strong><Progress equipment={e}/></div></div><div className="tabs" role="tablist">{[['readings','Lecturas'],['maintenances','Mantenciones'],['alerts','Alertas']].map(([id,label])=><button role="tab" aria-selected={tab===id} key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}>{label}</button>)}</div><div className="split-layout"><div className="panel history-panel"><h2>{tab==='readings'?'Cronología de lecturas':tab==='maintenances'?'Historial de mantenciones':'Historial de alertas'}</h2>{error&&<div role="alert" className="form-error">{error}</div>}{!history?<Empty>Cargando historial…</Empty>:<div className="table-responsive"><table className="vm-table"><thead><tr>{(tab==='readings'?['FECHA / HORA','LECTURA','VARIACIÓN','FUENTE','REGISTRADO POR']:tab==='maintenances'?['FECHA','SERVICIO','HORÓMETRO','ESTADO','TALLER']:['FECHA','MENSAJE','ESTADO']).map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{history[tab].map((item,index)=>tab==='readings'?<tr key={item.id}><td>{stamp(item.recorded_at)}</td><td>{fmt(item.value)} {e.unit}</td><td>{history.readings[index+1]?`+${fmt(Number(item.value)-Number(history.readings[index+1].value))}`:'—'}</td><td>{item.source==='ocr'?'OCR por foto':item.source==='sensor'?'Sensor':'Manual'}</td><td>{item.registered_by}</td></tr>:tab==='maintenances'?<tr key={item.id}><td>{date(item.scheduled_at)}</td><td>{item.service_type}</td><td>{fmt(item.value)} {e.unit}</td><td>{{completed:'Completada',scheduled:'Programada',draft:'Borrador',cancelled:'Cancelada'}[item.status]}</td><td>{item.workshop}</td></tr>:<tr key={item.id}><td>{stamp(item.created_at)}</td><td>{item.message}</td><td>{item.active?'Activa':'Atendida'}</td></tr>)}</tbody></table>{!history[tab].length&&<Empty/>}</div>}<p className="table-note">Los registros se conservan con su fecha, fuente y responsable.</p></div><aside><div className="panel"><h2>Última mantención</h2>{last?<><p>{stamp(last.completed_at)}</p><p>{last.service_type}</p><p>Referencia: {fmt(last.value)} {e.unit}</p><p>{last.description}</p></>:<p>Referencia inicial: {fmt(e.initial_service_value)} {e.unit}. Aún no se registran intervenciones completadas en el sistema.</p>}<small className="green-text">La próxima mantención se calcula automáticamente.</small></div>{e.status!=='operational'&&<Notice kind="red"><strong>Alerta activa · {e.code}</strong><p>{e.status_label}. Programa el servicio y registra su finalización para actualizar el intervalo.</p></Notice>}<div className="panel"><h2>Sensores asociados</h2>{history?.sensors.map(s=><p key={s.id}><strong>{s.identifier}</strong><br/>{s.sensor_type} · {s.active?'Activo':'Inactivo'}</p>)}</div></aside></div></>;
}

function MaintenancePage({equipment,maintenances,supplies,selectedId,can,mutate,busy,navigate}){
  const [editing,setEditing]=useState(null),[showLog,setShowLog]=useState(false);
  const [form,setForm]=useState({equipment:selectedId||equipment.find(e=>e.active)?.id||'',interval:250,value:'',service_type:'Preventiva · Servicio de motor',scheduled_at:localInput(),completed_at:localInput(),workshop:'',work_order:'',description:'',supplies:[]});
  const selected=equipment.find(e=>String(e.id)===String(form.equipment));
  const set=(key,value)=>setForm(f=>({...f,[key]:value}));
  useEffect(()=>{if(selected&&!editing)setForm(f=>({...f,value:selected.current_value,interval:selected.interval}));},[selected,editing]);
  async function save(status){const body={...form,status,scheduled_at:new Date(form.scheduled_at).toISOString(),completed_at:status==='completed'?new Date(form.completed_at).toISOString():null,supplies:form.supplies.filter(s=>s.supply).map(s=>({supply:Number(s.supply),quantity:s.quantity}))};if(await mutate(`maintenances/${editing?editing.id+'/':''}`,editing?'PATCH':'POST',body)){setEditing(null);setShowLog(true);}}
  function edit(item){setEditing(item);setForm({...item,scheduled_at:localInput(item.scheduled_at),completed_at:localInput(item.completed_at||new Date()),supplies:item.supplies.map(s=>({supply:s.supply,quantity:s.quantity}))});setShowLog(false);}
  if(showLog||!can('maintenance','C'))return <><PageHeader title="REGISTRO DE MANTENCIONES" subtitle="Intervenciones programadas, completadas y borradores de cada equipo.">{can('maintenance','C')&&<Button kind="primary" icon={Plus} onClick={()=>{setEditing(null);setShowLog(false);}}>Registrar mantención</Button>}</PageHeader><div className="table-responsive"><table className="vm-table"><thead><tr><th>EQUIPO</th><th>FECHA PROGRAMADA</th><th>SERVICIO</th><th>HORÓMETRO</th><th>ESTADO</th><th/></tr></thead><tbody>{maintenances.map(m=><tr key={m.id}><td><strong>{m.equipment_code}</strong><small>{m.workshop}</small></td><td>{stamp(m.scheduled_at)}</td><td>{m.service_type}</td><td>{fmt(m.value)}</td><td>{{completed:'Completada',scheduled:'Programada',draft:'Borrador',cancelled:'Cancelada'}[m.status]}</td><td>{can('maintenance','U')&&<button className="text-button red-text" onClick={()=>edit(m)}>Editar / Completar</button>}{m.status!=='cancelled'&&can('maintenance','D')&&<button className="text-button red-text" onClick={()=>{if(window.confirm('¿Cancelar esta mantención? El registro se conservará.'))mutate(`maintenances/${m.id}/`,'DELETE');}}>Cancelar</button>}</td></tr>)}</tbody></table>{!maintenances.length&&<Empty/>}</div></>;
  return <><PageHeader title="REGISTRAR MANTENCIÓN" subtitle="Documenta el servicio, registra el horómetro de referencia, el responsable y los insumos de la intervención."><Button icon={ClipboardList} onClick={()=>setShowLog(true)}>Ver registro de mantenciones</Button></PageHeader><div className="split-layout"><form className="panel service-form" onSubmit={e=>{e.preventDefault();save('completed');}}><div className="panel-title"><h2>{editing?'Editar intervención':`Registro de servicio · ${selected?.code||''}`}</h2><span className="eyebrow">EVIDENCIA DE MANTENCIÓN</span></div><div className="field-grid"><Field label="Equipo *"><Select required disabled={!!editing} value={form.equipment} onChange={e=>set('equipment',e.target.value)}>{equipment.filter(e=>e.active).map(e=><option value={e.id} key={e.id}>{e.code} · {e.name}</option>)}</Select></Field><Field label="Tipo de mantención *" required value={form.service_type} onChange={e=>set('service_type',e.target.value)}/><Field label="Intervalo de servicio *" type="number" min="1" required value={form.interval} onChange={e=>set('interval',e.target.value)}/><Field label="Horómetro de referencia *" type="number" min="0" step="0.01" required value={form.value} onChange={e=>set('value',e.target.value)}/><Field label="Inicio del servicio *" type="datetime-local" required value={form.scheduled_at} onChange={e=>set('scheduled_at',e.target.value)}/><Field label="Fecha / Hora de finalización *" type="datetime-local" max={localInput()} required value={form.completed_at} onChange={e=>set('completed_at',e.target.value)}/><Field label="Maestro / Taller *" required value={form.workshop} onChange={e=>set('workshop',e.target.value)} placeholder="Maestranza Vila · Taller Central"/><Field label="Orden de trabajo" value={form.work_order} onChange={e=>set('work_order',e.target.value)} placeholder="OT-2026-113"/></div><div className="panel-title"><h2>Insumos y repuestos</h2><button type="button" className="text-button red-text" onClick={()=>set('supplies',[...form.supplies,{supply:'',quantity:1}])}>+ Agregar insumo</button></div><div className="supply-list">{form.supplies.map((s,index)=><div className="supply-row" key={index}><Select aria-label={`Insumo ${index+1}`} required value={s.supply} onChange={e=>set('supplies',form.supplies.map((x,i)=>i===index?{...x,supply:e.target.value}:x))}><option value="">Seleccionar insumo</option>{supplies.filter(x=>x.active).map(x=><option key={x.id} value={x.id}>{x.description} · {x.unit}</option>)}</Select><input aria-label={`Cantidad ${index+1}`} type="number" min="0.01" step="0.01" required value={s.quantity} onChange={e=>set('supplies',form.supplies.map((x,i)=>i===index?{...x,quantity:e.target.value}:x))}/><button type="button" className="icon-button" aria-label={`Quitar insumo ${index+1}`} onClick={()=>set('supplies',form.supplies.filter((_,i)=>i!==index))}><X size={15}/></button></div>)}{!form.supplies.length&&<p className="muted">Agrega los insumos utilizados en la intervención.</p>}</div><Field label="Descripción del trabajo *"><textarea rows="3" required value={form.description} onChange={e=>set('description',e.target.value)} placeholder="Reemplazo de aceite y filtros de motor, inspección de mangueras y prueba de funcionamiento…"/></Field><div className="service-actions"><small>* Campos obligatorios. La finalización reinicia el intervalo.</small><div><Button type="button" disabled={busy} icon={Save} onClick={()=>save('draft')}>Guardar borrador</Button><Button type="button" disabled={busy} onClick={()=>save('scheduled')}>Programar</Button><Button kind="primary" icon={Check} disabled={busy||!selected}>Guardar registro completado</Button></div></div></form><aside><div className="panel context-panel"><h2>Contexto del equipo</h2>{selected&&<><Badge status={selected.status}/><p>{selected.code} · {selected.name}</p><div className="field-grid"><div><small>ACTUAL</small><h2>{fmt(selected.current_value)} {selected.unit}</h2></div><div><small>PRÓXIMA MANTENCIÓN</small><h2>{fmt(selected.next_service)} {selected.unit}</h2></div></div><Progress equipment={selected}/><hr/><h2>Cierre automático de alerta</h2><p>Al guardar una intervención completada se recalcula el próximo mantenimiento y se atiende la alerta que corresponda.</p><Notice><strong>Nueva referencia: {fmt(Number(form.value||0)+Number(selected.interval))} {selected.unit}</strong><p>El intervalo del equipo es {selected.interval} {selected.unit}.</p></Notice></>}</div><Notice kind="yellow"><strong>El estado actual de la flota se mantiene hasta confirmar la intervención.</strong><p>Un borrador o una programación no reinicia el intervalo ni cierra la alerta.</p></Notice></aside></div></>;
}

function CalendarPage({equipment,maintenances,can,navigate,exportFile}){
  const [month,setMonth]=useState(()=>new Date(new Date().getFullYear(),new Date().getMonth(),1)),[selected,setSelected]=useState(today()),[report,setReport]=useState(null),[error,setError]=useState('');
  useEffect(()=>{api(`report/?date=${selected}`).then(setReport).catch(e=>setError(e.message));},[selected,equipment,maintenances]);
  const offset=(month.getDay()+6)%7,days=new Date(month.getFullYear(),month.getMonth()+1,0).getDate(),cells=Array.from({length:Math.ceil((offset+days)/7)*7},(_,i)=>{const d=new Date(month.getFullYear(),month.getMonth(),i-offset+1);return {date:localInput(d).slice(0,10),day:d.getDate(),current:d.getMonth()===month.getMonth()};});
  const events=maintenances.filter(m=>m.status==='scheduled'),weekStart=new Date(selected+'T12:00:00');weekStart.setDate(weekStart.getDate()-((weekStart.getDay()+6)%7));const weekEnd=new Date(weekStart);weekEnd.setDate(weekStart.getDate()+6);
  const weekly=events.filter(m=>{const day=localInput(m.scheduled_at).slice(0,10);return day>=localInput(weekStart).slice(0,10)&&day<=localInput(weekEnd).slice(0,10);}).sort((a,b)=>a.scheduled_at.localeCompare(b.scheduled_at));
  const changeMonth=delta=>setMonth(m=>new Date(m.getFullYear(),m.getMonth()+delta,1));
  return <><PageHeader title="CALENDARIO DE MANTENCIÓN" subtitle="Planifica el mes, coordina la semana y exporta el informe diario de máquinas.">{can('maintenance','C')&&<Button kind="primary" icon={Check} onClick={()=>navigate('maintenance')}>Agendar mantención</Button>}</PageHeader><div className="split-layout calendar-layout"><div className="panel calendar-panel"><div className="calendar-title"><h2>{month.toLocaleDateString('es-CL',{month:'long',year:'numeric'})}</h2><div><button className="icon-button" aria-label="Mes anterior" onClick={()=>changeMonth(-1)}><ChevronLeft size={16}/></button><Button onClick={()=>{setMonth(new Date(new Date().getFullYear(),new Date().getMonth(),1));setSelected(today());}}>Hoy</Button><button className="icon-button" aria-label="Mes siguiente" onClick={()=>changeMonth(1)}><ChevronRight size={16}/></button></div></div><div className="calendar-grid">{['LUN','MAR','MIÉ','JUE','VIE','SÁB','DOM'].map(day=><div className="weekday" key={day}>{day}</div>)}{cells.map(cell=><button key={cell.date} className={`calendar-day ${cell.current?'':'outside'} ${cell.date===selected?'selected':''}`} onClick={()=>setSelected(cell.date)}><span>{cell.day}</span>{events.filter(m=>localInput(m.scheduled_at).slice(0,10)===cell.date).slice(0,2).map(m=><span className="calendar-event" key={m.id}>{m.equipment_code}<small>{m.service_type.split('·')[0]}</small></span>)}</button>)}</div><small className="input-help">Selecciona una fecha para consultar el estado de la flota al cierre de ese día.</small></div><div className="panel weekly-panel"><h2>Semana / {date(weekStart)} – {date(weekEnd)}</h2><div className="tabs"><span className="active">Semana</span></div>{weekly.map(m=><button className="weekly-event" key={m.id} onClick={()=>navigate('detail',m.equipment)}><strong>{stamp(m.scheduled_at)}</strong><span>{m.equipment_code} · {m.service_type}</span><small>{m.workshop}</small></button>)}{!weekly.length&&<Empty>No hay mantenciones programadas esta semana.</Empty>}</div></div><div className="panel daily-report"><div className="panel-title"><div><h2>Informe diario de máquinas / {date(selected+'T12:00:00')}</h2><p>El equipo · Lectura al cierre · Próxima mantención · Estado consolidado.</p></div><div className="heading-actions"><Button icon={Download} onClick={()=>exportFile('pdf',selected)}>Exportar PDF</Button><Button icon={Download} onClick={()=>exportFile('xlsx',selected)}>Exportar Excel</Button></div></div>{error&&<div className="form-error">{error}</div>}<div className="table-responsive"><table className="vm-table"><thead><tr><th>EQUIPO</th><th>LECTURA</th><th>PRÓXIMA MANT.</th><th>RESTANTE / EXCESO</th><th>ESTADO</th></tr></thead><tbody>{report?.equipment.map(e=><tr key={e.id}><td>{e.code} · {e.name}</td><td>{fmt(e.current_value)} {e.unit}</td><td>{fmt(e.next_service)} {e.unit}</td><td>{fmt(Math.abs(e.remaining))} {e.unit} {Number(e.remaining)<0?'vencido':'restantes'}</td><td><Badge status={e.status}/></td></tr>)}</tbody></table></div></div></>;
}

function AlertsPage({alerts,equipment,navigate,can,exportFile}){
  const [active,setActive]=useState('true'),[filter,setFilter]=useState(''),[severity,setSeverity]=useState('');
  const current=alerts.filter(a=>a.active),rows=alerts.filter(a=>(!active||String(a.active)===active)&&(!filter||String(a.equipment)===filter)&&(!severity||a.severity===severity)).sort((a,b)=>({overdue:0,required:1,upcoming:2}[a.severity]??3)-({overdue:0,required:1,upcoming:2}[b.severity]??3));
  return <><PageHeader title="ALERTAS DE MANTENCIÓN" subtitle="Prioriza las unidades más cercanas a su intervención y coordina su atención con anticipación."><Button icon={Download} onClick={()=>exportFile('xlsx')}>Exportar estado</Button></PageHeader><div className="stats-grid three"><Stat label="Alertas de mantención activas" value={current.length.toString().padStart(2,'0')} note="Equipos que requieren atención"/><Stat label="Atención inmediata" value={current.filter(a=>['overdue','required'].includes(a.severity)).length.toString().padStart(2,'0')} note="Vencidas o requeridas ahora" status="overdue"/><Stat label="Próximas a mantención" value={current.filter(a=>a.severity==='upcoming').length.toString().padStart(2,'0')} note="Planificar antes de finalizar el intervalo" status="upcoming"/></div><div className="toolbar"><Select aria-label="Filtrar alertas activas" value={active} onChange={e=>setActive(e.target.value)}><option value="true">Alertas activas</option><option value="false">Alertas atendidas</option><option value="">Todas las alertas</option></Select><Select aria-label="Filtrar alertas por equipo" value={filter} onChange={e=>setFilter(e.target.value)}><option value="">Todos los equipos</option>{equipment.map(e=><option key={e.id} value={e.id}>{e.code} · {e.name}</option>)}</Select><Select aria-label="Filtrar categoría de alerta" value={severity} onChange={e=>setSeverity(e.target.value)}><option value="">Todas las categorías de urgencia</option>{Object.entries(labels).filter(([s])=>s!=='operational').map(([s,l])=><option key={s} value={s}>{l}</option>)}</Select><span className="muted">Prioridad por urgencia y horas restantes</span></div><div className="table-responsive"><table className="vm-table"><thead><tr><th>ALERTA / EQUIPO</th><th>URGENCIA</th><th>LECTURA ACTUAL</th><th>CERCANÍA A MANTENCIÓN</th><th>ESTADO</th><th>ACCIÓN</th></tr></thead><tbody>{rows.map(a=><tr key={a.id}><td><small>A-{String(a.id).padStart(3,'0')} · {a.active?'Activa':'Atendida'}</small><strong>{a.equipment_code} · {a.equipment_name}</strong><small>{a.equipment_type}</small></td><td><Badge status={a.severity}/></td><td>{fmt(a.current_value)} {a.unit}</td><td className="progress-cell"><Progress equipment={{...a,status:a.severity}}/></td><td>{a.active?'Pendiente':date(a.attended_at)}</td><td><button className="text-button red-text" onClick={()=>navigate(can('maintenance','C')?'maintenance':'detail',a.equipment)}>{can('maintenance','C')?'Registrar servicio':'Ver historial'} →</button></td></tr>)}</tbody></table>{!rows.length&&<Empty/>}</div><div className="two-notices"><Notice kind="yellow"><strong>Cómo se ordena la cola</strong><p>Vencida → requerida → próxima. Registra el servicio completado para recalcular la próxima mantención.</p></Notice><Notice><strong>¿Qué cierra una alerta?</strong><p>Una mantención completada que deje al equipo fuera del tramo de riesgo. Una programación o un borrador no cierra la alerta.</p></Notice></div></>;
}

function UsersPage({users,can,mutate,busy}){
  const [search,setSearch]=useState(''),[role,setRole]=useState(''),[editing,setEditing]=useState(null),[access,setAccess]=useState('');
  const [form,setForm]=useState({first_name:'',last_name:'',email:'',role:'helper',region:'Norte',is_active:true,password:''});
  const start=item=>{setEditing(item||{});setForm({first_name:'',last_name:'',email:'',role:'helper',region:'Norte',is_active:true,password:'',...item});};
  const set=(key,value)=>setForm(f=>({...f,[key]:value}));
  async function submit(e){e.preventDefault();const body={...form};delete body.id;delete body.role_label;delete body.last_login;if(!body.password)delete body.password;if(await mutate(`users/${editing?.id?editing.id+'/':''}`,editing?.id?'PATCH':'POST',body))setEditing(null);}
  const rows=users.filter(u=>`${u.first_name} ${u.last_name} ${u.email}`.toLowerCase().includes(search.toLowerCase())&&(!role||u.role===role)&&(!access||String(u.is_active)===access));
  return <><PageHeader title="USUARIOS Y ROLES" subtitle="Otorga a cada persona el acceso que necesita. Las cuentas individuales mantienen la trazabilidad de cada acción.">{can('user','C')&&<Button kind="primary" icon={Check} onClick={()=>start()}>Crear usuario</Button>}</PageHeader><div className="toolbar"><SearchBox value={search} onChange={setSearch} placeholder="Buscar nombre o correo"/><Select aria-label="Filtrar rol" value={role} onChange={e=>setRole(e.target.value)}><option value="">Todos los roles</option>{Object.entries(roles).map(([r,l])=><option value={r} key={r}>{l}</option>)}</Select><Select aria-label="Filtrar acceso" value={access} onChange={e=>setAccess(e.target.value)}><option value="">Todos los estados de acceso</option><option value="true">Activo</option><option value="false">Inactivo</option></Select></div><div className={`split-layout ${editing?'':'no-aside'}`}><div className="table-responsive"><table className="vm-table"><thead><tr><th>USUARIO</th><th>ROL</th><th>ACCESO</th><th>ÚLTIMA ACTIVIDAD</th><th/></tr></thead><tbody>{rows.map(u=><tr key={u.id}><td><strong>{u.first_name} {u.last_name}</strong><small>{u.email}</small></td><td>{roles[u.role]}</td><td className={u.is_active?'green-text':'red-text'}>{u.is_active?'Activo':'Inactivo'}</td><td>{stamp(u.last_login)}</td><td>{can('user','U')&&<button className="text-button red-text" onClick={()=>start(u)}>Editar</button>}</td></tr>)}</tbody></table>{!rows.length&&<Empty/>}<p className="table-note">{rows.length} usuarios visibles · Cuentas individuales y acceso controlado.</p></div>{editing&&<form className="panel side-form" onSubmit={submit}><h2>{editing.id?`Editar usuario · ${editing.first_name}`:'Crear usuario'}</h2><div className="field-grid"><Field label="Nombre *" required value={form.first_name} onChange={e=>set('first_name',e.target.value)}/><Field label="Apellido *" required value={form.last_name} onChange={e=>set('last_name',e.target.value)}/></div><Field label="Correo corporativo *" type="email" required value={form.email} onChange={e=>set('email',e.target.value)}/><div className="field-grid"><Field label="Rol *"><Select value={form.role} onChange={e=>set('role',e.target.value)}>{Object.entries(roles).map(([r,l])=><option value={r} key={r}>{l}</option>)}</Select></Field><Field label="Estado de acceso"><Select value={String(form.is_active)} onChange={e=>set('is_active',e.target.value==='true')}><option value="true">Activo</option><option value="false">Inactivo</option></Select></Field></div><Field label="Faena / Región asignada" value={form.region} onChange={e=>set('region',e.target.value)}/><Field label={editing.id?'Nueva contraseña (opcional)':'Contraseña inicial *'} type="password" autoComplete="new-password" required={!editing.id} minLength="8" value={form.password} onChange={e=>set('password',e.target.value)}/><small className="input-help">Mínimo 8 caracteres, mayúsculas, minúsculas y números.</small><div className="form-actions"><Button type="button" onClick={()=>setEditing(null)}>Cancelar</Button><Button kind="primary" icon={Check} disabled={busy}>Guardar usuario</Button></div></form>}</div><div className="panel permissions-panel"><h2>Permisos de rol / Acceso de menor privilegio</h2><div className="table-responsive"><table className="vm-table"><thead><tr><th>FUNCIONALIDAD</th><th>ADMINISTRADOR</th><th>PLANIFICADOR</th><th>AYUDANTE</th><th>JEFE</th></tr></thead><tbody>{[['Equipos','CRUD','Crear, leer, editar','Crear y leer','Solo lectura'],['Lecturas de horómetro','CRUD','Crear, leer, editar','Crear y leer','Solo lectura'],['Mantenciones','CRUD','CRUD','Crear y leer','Solo lectura'],['Insumos y pautas','CRUD','Crear, leer, editar','Solo lectura','Solo lectura'],['Alertas / Calendario y reportes','Acceso total','Solo lectura','Solo lectura','Solo lectura'],['Usuarios y roles','CRUD','Sin acceso','Sin acceso','Solo lectura']].map(row=><tr key={row[0]}>{row.map((v,i)=><td key={i}>{v}</td>)}</tr>)}</tbody></table></div><small className="input-help">CRUD: crear, consultar, editar y dar de baja. Los permisos se verifican en el servidor.</small></div></>;
}

export default function App(){
  const [user,setUser]=useState(null),[initializing,setInitializing]=useState(true),[page,setPage]=useState(location.hash.slice(1)||'fleet'),[selectedId,setSelectedId]=useState(null),[menu,setMenu]=useState(false),[busy,setBusy]=useState(false),[loading,setLoading]=useState(false),[message,setMessage]=useState(null),[online,setOnline]=useState(navigator.onLine),[pending,setPending]=useState(0),[syncing,setSyncing]=useState(false);
  const [data,setData]=useState({equipment:[],readings:[],maintenances:[],alerts:[],users:[],supplies:[]});
  const can=useCallback((module,action)=>!!user?.permissions?.[module]?.includes(action),[user]);
  const refresh=useCallback(async()=>{if(!user)return;setLoading(true);try{const names=['equipment','readings','maintenances','alerts','supplies',...(user.permissions.user?.includes('R')?['users']:[])];const values=await Promise.all(names.map(name=>api(name+'/')));setData(Object.fromEntries(names.map((name,i)=>[name,values[i]])));}catch(e){setMessage({kind:'red',text:e.message});if(e.status===401)setUser(null);}finally{setLoading(false);}},[user]);
  useEffect(()=>{initCSRF().then(()=>api('auth/me/')).then(setUser).catch(e=>{if(e.status!==401)setMessage({kind:'red',text:'No se pudo conectar con Django. Comprueba que el backend esté iniciado.'});}).finally(()=>setInitializing(false));},[]);
  useEffect(()=>{refresh();},[refresh]);
  const sync=useCallback(async()=>{if(!user||!navigator.onLine)return;setSyncing(true);try{const count=await syncReadings(user.id);setPending((await pendingReadings(user.id)).length);if(count){setMessage({kind:'green',text:`${count} lecturas sincronizadas correctamente.`});await refresh();}}catch(e){setMessage({kind:'red',text:'No se pudo sincronizar: '+e.message+'. Los registros permanecen guardados en este dispositivo.'});}finally{setSyncing(false);}},[user,refresh]);
  useEffect(()=>{if(user){pendingReadings(user.id).then(items=>setPending(items.length));sync();}},[user,sync]);
  useEffect(()=>{const on=()=>{setOnline(true);sync();},off=()=>setOnline(false),hash=()=>setPage(location.hash.slice(1)||'fleet');window.addEventListener('online',on);window.addEventListener('offline',off);window.addEventListener('hashchange',hash);return()=>{window.removeEventListener('online',on);window.removeEventListener('offline',off);window.removeEventListener('hashchange',hash);};},[sync]);
  useEffect(()=>{if(!user)return;let timer;const activity=()=>{clearTimeout(timer);timer=setTimeout(()=>{api('auth/logout/',{method:'POST'}).catch(()=>{});setUser(null);setMessage({kind:'yellow',text:'Sesión cerrada por inactividad.'});},2*60*60*1000);};activity();window.addEventListener('pointerdown',activity);window.addEventListener('keydown',activity);return()=>{clearTimeout(timer);window.removeEventListener('pointerdown',activity);window.removeEventListener('keydown',activity);};},[user]);
  function navigate(target,id){if(id)setSelectedId(id);location.hash=target;setPage(target);setMenu(false);setMessage(null);}
  async function mutate(path,method,body){setBusy(true);setMessage(null);try{await api(path,{method,body});await refresh();setMessage({kind:'green',text:method==='DELETE'?'Registro desactivado o cancelado. Se conservó su historial.':'Registro guardado correctamente.'});return true;}catch(e){setMessage({kind:'red',text:e.message});if(e.status===401)setUser(null);return false;}finally{setBusy(false);}}
  async function exportFile(format,day=today()){try{await download(`report/?date=${day}&export=${format}`,`flota-${day}.${format}`);}catch(e){setMessage({kind:'red',text:e.message});}}
  if(initializing)return <div className="loading-screen"><Logo/><p>Conectando con el sistema de mantención…</p></div>;
  if(!user)return <>{message&&<div className={`connection-banner ${message.kind}`} role="alert">{message.text}</div>}<Login onLogin={u=>{setUser(u);setMessage(null);navigate('fleet');}}/></>;
  const allowed=modules.filter(m=>m.id!=='users'||can('user','R'));
  const current=allowed.some(m=>m.id===page)?page:'fleet';
  const props={...data,can,navigate,selectedId,mutate,busy,user,exportFile,onQueued:async()=>{setPending((await pendingReadings(user.id)).length);setMessage({kind:'yellow',text:'Lectura guardada en este dispositivo. Se sincronizará al recuperar la conexión.'});}};
  return <div className="app-shell"><aside className={`sidebar ${menu?'open':''}`}><Logo/><div className="work-context"><span className="eyebrow">CAMPO DE TRABAJO</span><strong>Norte</strong><small>Operaciones industriales</small></div><nav>{allowed.map(m=><button key={m.id} className={current===m.id?'active':''} onClick={()=>navigate(m.id)}><m.icon size={15}/><span>{m.label}</span></button>)}</nav><div className="sidebar-bottom"><div className={`connection-status ${online?'':'offline'}`}><strong>{online?'Todos los sistemas conectados':'Sin conexión'}</strong><span>{syncing?'Sincronizando lecturas…':pending?`${pending} lecturas pendientes`:'Última consulta · en línea'}</span>{pending>0&&online&&<button className="text-button" onClick={sync} disabled={syncing}>Sincronizar ahora</button>}</div><small>Datos de equipo <FileText size={10}/></small><span className="muted">Vila’s Motor · v1.0</span><button className="text-button" onClick={()=>exportFile('pdf')}>Ver informe diario →</button></div></aside>{menu&&<div className="sidebar-overlay" onClick={()=>setMenu(false)}/>}
    <div className="workspace"><header className="topbar"><div className="mobile-topbrand"><Logo/><button className="icon-button" aria-label="Abrir menú" onClick={()=>setMenu(!menu)}><Menu size={21}/></button></div><span className="breadcrumb-vm">Norte / Equipo de operaciones</span><div className="topbar-right"><time>{stamp(new Date())}</time><button className="icon-button" aria-label="Ver alertas" onClick={()=>navigate('alerts')}><Bell size={16}/></button><div className="avatar">{user.first_name?.[0]}{user.last_name?.[0]}</div><div className="user-meta"><strong>{user.first_name} {user.last_name}</strong><small>{roles[user.role]}</small></div><button className="icon-button" aria-label="Cerrar sesión" title="Cerrar sesión" onClick={async()=>{try{await api('auth/logout/',{method:'POST'});setUser(null);}catch(e){setMessage({kind:'red',text:e.message});}}}><LogOut size={16}/></button></div></header>
    <main className="main-content">{message&&<div className={`message-bar ${message.kind}`} role={message.kind==='red'?'alert':'status'}><span>{message.text}</span><button className="icon-button" aria-label="Cerrar mensaje" onClick={()=>setMessage(null)}><X size={16}/></button></div>}{loading&&!data.equipment.length?<Empty>Cargando la flota…</Empty>:current==='fleet'?<Fleet {...props}/>:current==='equipment'?<EquipmentPage {...props}/>:current==='readings'?<ReadingsPage {...props}/>:current==='detail'?<DetailPage {...props}/>:current==='maintenance'?<MaintenancePage {...props}/>:current==='calendar'?<CalendarPage {...props}/>:current==='alerts'?<AlertsPage {...props}/>:<UsersPage {...props}/>}<footer className="page-footer"><span>NORTE · INFORMACIÓN OPERACIONAL DE FLOTA</span><span>{online?'Conectado al sistema':'Trabajo sin conexión'} · Vila’s Motor</span></footer></main></div><nav className="mobile-bottom-nav">{[['fleet',LayoutDashboard,'Flota'],['readings',Gauge,'Lecturas'],['alerts',Bell,'Alertas'],['calendar',CalendarDays,'Agenda']].map(([id,Icon,label])=><button className={current===id?'active':''} key={id} onClick={()=>navigate(id)}><Icon size={20}/><span>{label}</span></button>)}</nav></div>;
}
